const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  // 50 4b = "PK", the ZIP signature
  if (!(buf[0] === 0x50 && buf[1] === 0x4b)) {
    throw new Error('Intercom export is not a ZIP archive (first bytes ' + buf.subarray(0, 4).toString('hex') + ')');
  }
  out.push({
    json: items[i].json,
    binary: { data: { ...items[i].binary.data, fileName: 'intercom-export.zip', fileExtension: 'zip', mimeType: 'application/zip' } },
  });
}
return out;

const week = $('COMPUTE REPORTING WEEK').first().json;
const startMs = week.week_start_unix * 1000;
const endMs = (week.week_end_unix + 1) * 1000;
const inWeek = ts => { const t = Date.parse(ts); return t >= startMs && t < endMs; };
const bin = $input.first().binary || {};

// RFC 4180 parser: titles can contain commas, quotes and line breaks
function parseCsv(src) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (inQuotes) {
      if (ch === '"') {
        if (src[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else {
        field += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ',') {
      row.push(field); field = '';
    } else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && src[i + 1] === '\n') { i++; }
      row.push(field); rows.push(row); row = []; field = '';
    } else {
      field += ch;
    }
  }
  if (field !== '' || row.length > 0) { row.push(field); rows.push(row); }
  return rows.filter(r => !(r.length === 1 && r[0] === ''));
}

// Unzipped files are named <stat>_<timestamp>.csv; a stat with no records is simply absent
async function readTable(prefix) {
  const key = Object.keys(bin).find(k => (bin[k].fileName || '').startsWith(prefix));
  if (!key) return null;
  const table = parseCsv((await this.helpers.getBinaryDataBuffer(0, key)).toString('utf-8').replace(/^﻿/, ''));
  return { header: table[0] || [], rows: table.slice(1) };
}

const receipts = await readTable.call(this, 'receipt_');
if (!receipts) {
  throw new Error('Intercom export has no receipt_*.csv. Files: ' + Object.keys(bin).map(k => bin[k].fileName).join(', '));
}
const col = name => receipts.header.indexOf(name);
const required = ['receipt_id', 'content_type', 'content_id', 'content_title', 'series_id', 'series_title', 'received_at'];
const missing = required.filter(name => col(name) === -1);
if (missing.length > 0) {
  throw new Error('receipt CSV is missing columns: ' + missing.join(', ') + '. Intercom may have changed the export format.');
}

// Every Series email seen in the lookback window; receipt_id -> email key for the event files
const emails = {};
const emailOfReceipt = {};
for (const r of receipts.rows) {
  if (r[col('content_type')] !== 'email') continue;
  const seriesId = r[col('series_id')];
  if (!seriesId || seriesId === '-1') continue;
  const seriesTitle = r[col('series_title')].trim();
  if (/test/i.test(seriesTitle)) continue;

  const key = seriesId + '|' + r[col('content_id')];
  emailOfReceipt[r[col('receipt_id')]] = key;
  if (!emails[key]) {
    emails[key] = {
      seriesId, seriesTitle, message: r[col('content_title')].trim(),
      sent: 0, opened: new Set(), clicked: new Set(), replied: new Set(), unsubscribed: new Set(), bounced: new Set(),
    };
  }
  if (inWeek(r[col('received_at')])) emails[key].sent++;
}

// Engagement is counted when it happened (Intercom UI behaviour), once per delivered email
async function countEvents(prefix, stat) {
  const table = await readTable.call(this, prefix);
  if (!table) return;
  const receiptCol = table.header.indexOf('receipt_id');
  const timeCol = table.header.findIndex(h => h.endsWith('_at'));
  for (const r of table.rows) {
    const key = emailOfReceipt[r[receiptCol]];
    if (key && inWeek(r[timeCol])) emails[key][stat].add(r[receiptCol]);
  }
}
await countEvents.call(this, 'open_', 'opened');
await countEvents.call(this, 'click_', 'clicked');
await countEvents.call(this, 'reply_', 'replied');
await countEvents.call(this, 'unsubscribe_', 'unsubscribed');
await countEvents.call(this, 'hard_bounce_', 'bounced');
await countEvents.call(this, 'soft_bounce_', 'bounced');

const hasActivity = e => e.sent + e.opened.size + e.clicked.size + e.replied.size + e.unsubscribed.size + e.bounced.size > 0;
const all = Object.values(emails);

// Stale-export guard: a normal week always has some Series activity
if (!all.some(hasActivity)) {
  throw new Error('No Series email activity found inside the ' + week.week_start_date + ' week (' + all.length + ' emails in the lookback). The export looks like it covers a different period; nothing was written.');
}

// A series that had any activity this week gets a row for every one of its emails, zeros included
const activeSeries = new Set(all.filter(hasActivity).map(e => e.seriesId));

// Duplicate guard: skip Series ID + message pairs already logged for this week's Date
const [y, m, d] = week.week_start_date.split('-').map(Number);
const dateSerial = Date.UTC(y, m - 1, d) / 86400000 + 25569;
const alreadyLogged = new Set(
  $('READ ROWS ALREADY LOGGED').all()
    .map(item => item.json)
    .filter(row => row.Date === dateSerial || row.Date === week.week_start_date)
    .map(row => String(row['Series ID'] ?? '').trim() + '|' + String(row['Series Name'] ?? '').trim())
);

const pct = (n, total) => (total > 0 ? (n / total * 100) : 0).toFixed(2) + '%';

return all
  .filter(e => activeSeries.has(e.seriesId))
  .filter(e => !alreadyLogged.has(e.seriesId + '|' + e.message))
  .sort((a, b) => (a.seriesTitle + ' ' + a.message).localeCompare(b.seriesTitle + ' ' + b.message))
  .map(e => ({
    json: {
      'Date': week.week_start_date,
      'Series ID': e.seriesId,
      'Intercom URL': `https://app.intercom.com/a/apps/j4h8h6vo/outbound/series/${e.seriesId}`,
      'Series Name': e.message,
      'Total sent': e.sent,
      'Open rate': pct(e.opened.size, e.sent),
      'Opened': e.opened.size,
      'Click rate': pct(e.clicked.size, e.sent),
      'Clicked': e.clicked.size,
      'Reply rate': pct(e.replied.size, e.sent),
      'Replied': e.replied.size,
      'Unsubscribe rate': pct(e.unsubscribed.size, e.sent),
      'Unsubscribed': e.unsubscribed.size,
      'Bounce rate': pct(e.bounced.size, e.sent),
      'Bounced': e.bounced.size,
    },
  }));
